// Regenerates the verbatim type listing in docs/CONTRACTS.md from src/core/types/*.ts.
// Usage: npm run docs:contracts   (a unit test fails if CONTRACTS.md is out of sync)
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const typesDir = join(root, 'src', 'core', 'types');
const docPath = join(root, 'docs', 'CONTRACTS.md');
const BEGIN =
  '<!-- CONTRACTS:BEGIN (generated by scripts/sync-contracts.mjs — do not edit by hand) -->';
const END = '<!-- CONTRACTS:END -->';

const files = readdirSync(typesDir)
  .filter((f) => f.endsWith('.ts'))
  .sort((a, b) => (a === 'index.ts' ? 1 : b === 'index.ts' ? -1 : a.localeCompare(b)));

const body = files
  .map((f) => {
    const src = readFileSync(join(typesDir, f), 'utf8').replace(/\r\n/g, '\n').trimEnd();
    return `### \`src/core/types/${f}\`\n\n\`\`\`ts\n${src}\n\`\`\``;
  })
  .join('\n\n');

const doc = readFileSync(docPath, 'utf8').replace(/\r\n/g, '\n');
const start = doc.indexOf(BEGIN);
const end = doc.indexOf(END);
if (start === -1 || end === -1) throw new Error(`Markers not found in ${docPath}`);

const next = `${doc.slice(0, start)}${BEGIN}\n\n${body}\n\n${doc.slice(end)}`;
writeFileSync(docPath, next);
console.log(`CONTRACTS.md synced from ${files.length} files.`);
